def minTotalPeak(jobs, d):
    n = len(jobs)
    if n < d:
        return -1
    INF = 10 ** 9
    prev = [INF] * (n + 1)
    prev[0] = 0
    for day in range(1, d + 1):
        cur = [INF] * (n + 1)
        for i in range(day, n + 1):
            m = 0
            best = INF
            for t in range(i - 1, day - 2, -1):
                if jobs[t] > m:
                    m = jobs[t]
                v = prev[t] + m
                if v < best:
                    best = v
            cur[i] = best
        prev = cur
    return prev[n]
